import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

interface Delivery {
  _id: string;
  customerId: string;
  driverId?: string;
  address: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

interface Driver {
  _id: string;
  name: string;
  email?: string;
  phone?: string;
  address?: string;
}

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function DeliveryDetailsPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [delivery, setDelivery] = useState<Delivery | null>(null);
  const [driver, setDriver] = useState<Driver | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!id) {
      setError("❗ No delivery ID provided.");
      setLoading(false);
      return;
    }

    const fetchData = async () => {
      try {
        const deliveryRes = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        const deliveryData = deliveryRes.data;
        setDelivery(deliveryData);

        if (deliveryData.driverId) {
          const driverRes = await axios.get(`${API_BASE_URL}/api/drivers/${deliveryData.driverId}`);
          const driverData = driverRes.data;
          setDriver(driverData); // ✅ Save full driver
        }

        setLoading(false);
      } catch (err) {
        console.error("Error fetching delivery or driver:", err);
        setError("❌ Failed to fetch delivery or driver details");
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  if (loading) return <div>Loading...</div>;
  if (error || !delivery) return <div>{error || "Delivery not found"}</div>;

  const googleMapsLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(delivery.address)}`;

  return (
    <div style={{ padding: "20px" }}>
      <h2>📦 Delivery Details</h2>

      <p><strong>Customer ID:</strong> {delivery.customerId}</p>
      <p><strong>Status:</strong> {delivery.status}</p>
      <p><strong>Driver ID:</strong> {delivery.driverId || "Not assigned"}</p>
      <p><strong>Driver Name:</strong> {driver?.name || "Not assigned"}</p>
      <p><strong>Driver Phone:</strong> {driver?.phone || "Not available"}</p>
      <p><strong>Delivery Address:</strong> {delivery.address}</p>

      {driver?.phone && (
        <div style={{ marginTop: "10px" }}>
          <a href={`tel:${driver.phone}`}>
            <button style={callButtonStyle}>📞 Call Driver</button>
          </a>
        </div>
      )}

      <div style={{ marginTop: "20px", display: "flex", gap: "1rem" }}>
        <button
          onClick={() => navigate("/")}
          style={backButtonStyle}
        >
          ← Back to Dashboard
        </button>

        <button
          onClick={() => navigate(`/tracking/${delivery._id}`)}
          style={trackButtonStyle}
        >
          🚚 Track Delivery
        </button>

        <a
          href={googleMapsLink}
          target="_blank"
          rel="noopener noreferrer"
        >
          <button style={mapButtonStyle}>
            📍 Open in Google Maps
          </button>
        </a>
      </div>
    </div>
  );
}

const backButtonStyle = {
  padding: "10px 20px",
  backgroundColor: "#6c757d",
  color: "#fff",
  border: "none",
  borderRadius: "4px",
  cursor: "pointer",
};

const trackButtonStyle = {
  padding: "10px 20px",
  backgroundColor: "#007bff",
  color: "#fff",
  border: "none",
  borderRadius: "4px",
  cursor: "pointer",
};

const mapButtonStyle = {
  padding: "10px 20px",
  backgroundColor: "#007bff",
  color: "#fff",
  border: "none",
  borderRadius: "4px",
  cursor: "pointer",
};

const callButtonStyle = {
  padding: "10px 20px",
  backgroundColor: "#28a745",
  color: "#fff",
  border: "none",
  borderRadius: "4px",
  cursor: "pointer",
};
